-- 2. Roles extension ---------------------------------------------------------
alter table public.roles add column if not exists is_system_role boolean not null default false;
alter table public.roles add column if not exists is_active boolean not null default true;
alter table public.roles add column if not exists created_by uuid;
alter table public.roles add column if not exists updated_at timestamptz not null default now();

-- 3. Role permissions --------------------------------------------------------
create table if not exists public.role_permissions (
  id uuid primary key default gen_random_uuid(),
  role_id uuid not null references public.roles(id) on delete cascade,
  permission_id uuid not null references public.permissions(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (role_id, permission_id)
);
create index if not exists role_permissions_role_idx on public.role_permissions (role_id);

-- 4. User permissions v2 -----------------------------------------------------
alter table public.user_permissions add column if not exists effect text not null default 'allow';
alter table public.user_permissions drop constraint if exists user_permissions_effect_check;
alter table public.user_permissions add constraint user_permissions_effect_check check (effect in ('allow', 'deny'));
alter table public.user_permissions add column if not exists reason text;
alter table public.user_permissions add column if not exists starts_at timestamptz;
alter table public.user_permissions add column if not exists expires_at timestamptz;
alter table public.user_permissions add column if not exists permission_id uuid references public.permissions(id) on delete set null;
alter table public.user_permissions alter column granted_by drop not null;

-- 5. Teams -------------------------------------------------------------------
create table if not exists public.teams (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  description text not null default '',
  created_by uuid references public.profiles(id) on delete set null,
  visibility text not null default 'team' check (visibility in ('private', 'team', 'organisation')),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.team_members (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references public.teams(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  team_role text not null default 'team_member' check (team_role in ('team_owner', 'team_manager', 'team_member')),
  joined_at timestamptz not null default now(),
  unique (team_id, user_id)
);
create index if not exists team_members_user_idx on public.team_members (user_id);

-- 6. Projects ----------------------------------------------------------------
create table if not exists public.projects (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  description text not null default '',
  owner_id uuid references public.profiles(id) on delete set null,
  team_id uuid references public.teams(id) on delete set null,
  visibility text not null default 'team' check (visibility in ('private', 'team', 'organisation')),
  status text not null default 'active' check (status in ('active', 'archived', 'completed')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.project_members (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  project_role text not null default 'member' check (project_role in ('owner', 'manager', 'member')),
  added_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (project_id, user_id)
);
create index if not exists project_members_user_idx on public.project_members (user_id);

-- 7. Resource access ---------------------------------------------------------
create table if not exists public.resource_access (
  id uuid primary key default gen_random_uuid(),
  resource_type text not null check (resource_type in ('engagement', 'project', 'document', 'report', 'journal_entry', 'team')),
  resource_id uuid not null,
  user_id uuid not null references public.profiles(id) on delete cascade,
  access_level text not null check (access_level in ('view', 'contribute', 'edit', 'manage')),
  granted_by uuid references public.profiles(id) on delete set null,
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  unique (resource_type, resource_id, user_id)
);
create index if not exists resource_access_user_idx on public.resource_access (user_id);
create index if not exists resource_access_resource_idx on public.resource_access (resource_type, resource_id);

-- 8. Approval requests -------------------------------------------------------
create table if not exists public.approval_requests (
  id uuid primary key default gen_random_uuid(),
  request_type text not null,
  resource_type text not null,
  resource_id uuid,
  requested_by uuid not null references public.profiles(id) on delete cascade,
  assigned_approver uuid references public.profiles(id) on delete set null,
  status text not null default 'Pending' check (status in ('Pending', 'Approved', 'Rejected', 'Cancelled')),
  reason text not null default '',
  decision_note text,
  payload jsonb not null default '{}'::jsonb,
  expires_at timestamptz,
  decided_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists approval_requests_approver_idx on public.approval_requests (assigned_approver, status);
create index if not exists approval_requests_requester_idx on public.approval_requests (requested_by, status);

-- 9. Leave requests (employee self-service) ----------------------------------
create table if not exists public.leave_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  leave_type text not null default 'annual',
  starts_on date not null,
  ends_on date not null,
  reason text not null default '',
  status text not null default 'Pending' check (status in ('Pending', 'Approved', 'Rejected', 'Cancelled')),
  decided_by uuid references public.profiles(id) on delete set null,
  decision_note text,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  check (ends_on >= starts_on)
);
create index if not exists leave_requests_user_idx on public.leave_requests (user_id, status);

