alter table public.audit_events add column if not exists previous_state jsonb;
alter table public.audit_events add column if not exists new_state jsonb;
alter table public.audit_events add column if not exists request_id text;
alter table public.audit_events add column if not exists source text;
alter table public.audit_events add column if not exists reason text;
alter table public.audit_events add column if not exists actor_role_title text;

-- 11. Helper functions -------------------------------------------------------
-- All helpers are SECURITY DEFINER with a pinned search_path and fully
-- qualified references. They evaluate effective permissions from the
-- catalogue: active deny beats everything; then admin bypass except for the
-- explicitly restricted keys; then explicit allow; then role grants.

create or replace function public.current_user_is_active()
returns boolean language sql security definer set search_path = public stable
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.active and p.approval_status = 'approved'
  );
$$;

create or replace function public.current_user_is_admin()
returns boolean language sql security definer set search_path = public stable
as $$
  select exists (
    select 1 from public.profiles p
    left join public.roles r on r.id = p.role_id
    where p.id = auth.uid() and p.active
      and (p.is_admin or coalesce(r.name, '') in ('CEO', 'CEO / Managing Partner', 'Managing Partner', 'Administrator', 'System Administrator'))
  );
$$;

create or replace function public.current_user_has_permission(permission_key text)
returns boolean language sql security definer set search_path = public stable
as $$
  select public.current_user_is_active()
    and not exists (
      select 1 from public.user_permissions up
      where up.user_id = auth.uid()
        and up.permission_key = current_user_has_permission.permission_key
        and up.effect = 'deny'
        and (up.starts_at is null or up.starts_at <= now())
        and (up.expires_at is null or up.expires_at > now())
    )
    and (
      exists (
        select 1 from public.user_permissions up
        where up.user_id = auth.uid()
          and up.permission_key = current_user_has_permission.permission_key
          and up.effect = 'allow'
          and (up.starts_at is null or up.starts_at <= now())
          and (up.expires_at is null or up.expires_at > now())
      )
      or exists (
        select 1
        from public.profiles p
        join public.role_permissions rp on rp.role_id = p.role_id
        join public.permissions perm on perm.id = rp.permission_id
        join public.roles r on r.id = p.role_id
        where p.id = auth.uid() and p.active and r.is_active
          and perm.permission_key = current_user_has_permission.permission_key
      )
      or (public.current_user_is_admin()
          and not (current_user_has_permission.permission_key = any (array['view_payroll', 'view_confidential_documents'])))
    );
$$;

create or replace function public.current_user_effective_permissions()
returns setof text language sql security definer set search_path = public stable
as $$
  with deny as (
    select up.permission_key from public.user_permissions up
    where up.user_id = auth.uid() and up.effect = 'deny'
      and (up.starts_at is null or up.starts_at <= now())
      and (up.expires_at is null or up.expires_at > now())
  ), granted as (
    select up.permission_key from public.user_permissions up
    where up.user_id = auth.uid() and up.effect = 'allow'
      and (up.starts_at is null or up.starts_at <= now())
      and (up.expires_at is null or up.expires_at > now())
    union
    select perm.permission_key
    from public.profiles p
    join public.role_permissions rp on rp.role_id = p.role_id
    join public.permissions perm on perm.id = rp.permission_id
    join public.roles r on r.id = p.role_id
    where p.id = auth.uid() and p.active and r.is_active
    union
    select perm.permission_key from public.permissions perm
    where public.current_user_is_admin()
      and perm.permission_key <> all (array['view_payroll', 'view_confidential_documents'])
  )
  select g.permission_key from granted g where not exists (select 1 from deny d where d.permission_key = g.permission_key)
  union select perm.permission_key from public.permissions perm where perm.permission_key = 'view_dashboard' and public.current_user_is_admin();
$$;

create or replace function public.current_user_is_team_member(target_team_id uuid)
returns boolean language sql security definer set search_path = public stable
as $$
  select exists (
    select 1 from public.team_members tm where tm.team_id = target_team_id and tm.user_id = auth.uid()
  ) or public.current_user_is_admin();
$$;

create or replace function public.current_user_can_access_project(target_project_id uuid)
returns boolean language sql security definer set search_path = public stable
as $$
  select exists (
    select 1 from public.projects pr
    left join public.team_members tm on tm.team_id = pr.team_id and tm.user_id = auth.uid()
    where pr.id = target_project_id
      and (
        pr.owner_id = auth.uid()
        or exists (select 1 from public.project_members pm where pm.project_id = pr.id and pm.user_id = auth.uid())
        or tm.user_id is not null
        or (pr.visibility = 'organisation' and public.current_user_is_active())
      )
  ) or public.current_user_is_admin();
$$;

create or replace function public.current_user_can_access_resource(target_type text, target_id uuid, required_level text)
returns boolean language plpgsql security definer set search_path = public stable
as $$
declare
  levels constant text[] := array['view', 'contribute', 'edit', 'manage'];
  need int;
  have int;
begin
  if not (target_type = any (array['engagement', 'project', 'document', 'report', 'journal_entry', 'team'])) then
    raise exception 'Unknown resource type %', target_type;
  end if;
  if not (required_level = any (levels)) then
    raise exception 'Unknown access level %', required_level;
  end if;
  need := array_position(levels, required_level);
  if public.current_user_is_admin() then
    return true;
  end if;
  select max(array_position(levels, ra.access_level)) into have
  from public.resource_access ra
  where ra.resource_type = target_type and ra.resource_id = target_id and ra.user_id = auth.uid()
    and (ra.expires_at is null or ra.expires_at > now());
  return coalesce(have, 0) >= need;
end;
$$;

-- Legacy helper kept for the 005 policies until migration 011 re-keys them.
create or replace function public.current_profile_has_permission(permission_key text)
returns boolean language sql security definer set search_path = public stable
as $$
  select public.current_user_has_permission(current_profile_has_permission.permission_key);
$$;

create or replace function public.current_profile_is_admin()
returns boolean language sql security definer set search_path = public stable
as $$
  select public.current_user_is_admin();
$$;

-- 12. Guard triggers ---------------------------------------------------------
create or replace function public.rbac_catalogue_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.permissions p where p.permission_key = NEW.permission_key) then
    raise exception 'Unknown permission key % — it is not in the permission catalogue', NEW.permission_key;
  end if;
  select p.id into NEW.permission_id from public.permissions p where p.permission_key = NEW.permission_key;
  if TG_OP = 'UPDATE' and OLD.permission_key <> NEW.permission_key then
    raise exception 'Permission keys cannot be changed — revoke and re-grant instead';
  end if;
  return NEW;
end;
$$;
drop trigger if exists user_permissions_catalogue_guard on public.user_permissions;
create trigger user_permissions_catalogue_guard before insert or update on public.user_permissions
  for each row execute function public.rbac_catalogue_guard();

create or replace function public.profiles_privilege_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    return NEW;
  end if;
  if (NEW.role_id is distinct from OLD.role_id) or (NEW.is_admin is distinct from OLD.is_admin)
     or (NEW.approval_status is distinct from OLD.approval_status) or (NEW.active is distinct from OLD.active) then
    if not public.current_user_is_admin() then
      raise exception 'Role, administrator status, approval status and active status can only be changed by an administrator';
    end if;
  end if;
  return NEW;
end;
$$;
drop trigger if exists profiles_privilege_guard on public.profiles;
create trigger profiles_privilege_guard before update on public.profiles
  for each row execute function public.profiles_privilege_guard();

create or replace function public.audit_events_append_only()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then
    raise exception 'Audit log entries are append-only';
  end if;
  return NEW;
end;
$$;
drop trigger if exists audit_events_append_only on public.audit_events;
create trigger audit_events_append_only before update or delete on public.audit_events
  for each row execute function public.audit_events_append_only();

create or replace function public.journal_entries_sod_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    return NEW;
  end if;
  if TG_OP = 'INSERT' then
    if NEW.status in ('Posted', 'Reversed') and NEW.created_by = auth.uid() and not public.current_user_is_admin() then
      raise exception 'Segregation of duties: you cannot post a journal entry you created';
    end if;
    return NEW;
  end if;
  if NEW.status is distinct from OLD.status and NEW.status in ('Approved', 'Posted', 'Reversed') then
    if auth.uid() = OLD.created_by and not public.current_user_is_admin() then
      raise exception 'Segregation of duties: you cannot approve, post or reverse a journal entry you created';
    end if;
  end if;
  return NEW;
end;
$$;
drop trigger if exists journal_entries_sod_guard on public.journal_entries;
create trigger journal_entries_sod_guard before insert or update on public.journal_entries
  for each row execute function public.journal_entries_sod_guard();

-- Status-transition guards: a requester may cancel their own request but can
-- never approve it. Team and project owners cannot mint elevated team roles.
create or replace function public.approval_requests_status_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    return NEW;
  end if;
  if NEW.status is distinct from OLD.status then
    if NEW.status in ('Approved', 'Rejected') and not (NEW.assigned_approver = auth.uid() or public.current_user_has_permission('assign_permissions') or public.current_user_is_admin()) then
      raise exception 'Only the assigned approver or an authorised administrator can decide this request';
    end if;
    if NEW.status = 'Cancelled' and OLD.requested_by <> auth.uid() and not public.current_user_is_admin() then
      raise exception 'Only the requester can cancel this request';
    end if;
  end if;
  return NEW;
end;
$$;
drop trigger if exists approval_requests_status_guard on public.approval_requests;
create trigger approval_requests_status_guard before update on public.approval_requests
  for each row execute function public.approval_requests_status_guard();

create or replace function public.leave_requests_status_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    return NEW;
  end if;
  if NEW.status is distinct from OLD.status then
    if NEW.status in ('Approved', 'Rejected') and not (public.current_user_has_permission('approve_leave') or public.current_user_has_permission('manage_leave') or public.current_user_is_admin()) then
      raise exception 'Leave decisions require the approve-leave permission';
    end if;
    if NEW.status = 'Cancelled' and OLD.user_id <> auth.uid() and not public.current_user_is_admin() then
      raise exception 'Only the requester can cancel a leave request';
    end if;
  end if;
  return NEW;
end;
$$;
drop trigger if exists leave_requests_status_guard on public.leave_requests;
create trigger leave_requests_status_guard before update on public.leave_requests
  for each row execute function public.leave_requests_status_guard();

create or replace function public.membership_role_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    return NEW;
  end if;
  if TG_TABLE_NAME = 'team_members' and NEW.team_role in ('team_owner', 'team_manager')
     and not (public.current_user_has_permission('manage_teams') or public.current_user_is_admin()) then
    raise exception 'Elevated team roles require the manage-teams permission';
  end if;
  if TG_TABLE_NAME = 'project_members' and NEW.project_role in ('owner', 'manager')
     and not (public.current_user_has_permission('manage_project_members') or public.current_user_is_admin()) then
    raise exception 'Elevated project roles require the manage-project-members permission';
  end if;
  return NEW;
end;
$$;
drop trigger if exists team_members_role_guard on public.team_members;
create trigger team_members_role_guard before insert or update on public.team_members
  for each row execute function public.membership_role_guard();
drop trigger if exists project_members_role_guard on public.project_members;
create trigger project_members_role_guard before insert or update on public.project_members
  for each row execute function public.membership_role_guard();

-- 13. Grants -----------------------------------------------------------------
revoke all on function public.current_user_is_active() from public;
revoke all on function public.current_user_is_admin() from public;
revoke all on function public.current_user_has_permission(text) from public;
revoke all on function public.current_user_effective_permissions() from public;
revoke all on function public.current_user_is_team_member(uuid) from public;
revoke all on function public.current_user_can_access_project(uuid) from public;
revoke all on function public.current_user_can_access_resource(text, uuid, text) from public;
grant execute on function public.current_user_is_active() to authenticated, service_role;
grant execute on function public.current_user_is_admin() to authenticated, service_role;
grant execute on function public.current_user_has_permission(text) to authenticated, service_role;
grant execute on function public.current_user_effective_permissions() to authenticated, service_role;
grant execute on function public.current_user_is_team_member(uuid) to authenticated, service_role;
grant execute on function public.current_user_can_access_project(uuid) to authenticated, service_role;
grant execute on function public.current_user_can_access_resource(text, uuid, text) to authenticated, service_role;

-- 14. RLS for the new tables -------------------------------------------------
alter table public.permissions enable row level security;
alter table public.role_permissions enable row level security;
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.projects enable row level security;
alter table public.project_members enable row level security;
alter table public.resource_access enable row level security;
alter table public.approval_requests enable row level security;
alter table public.leave_requests enable row level security;

drop policy if exists "catalogue is readable by authenticated users" on public.permissions;
create policy "catalogue is readable by authenticated users" on public.permissions
  for select to authenticated using (true);

drop policy if exists "role permissions are readable by authenticated users" on public.role_permissions;
create policy "role permissions are readable by authenticated users" on public.role_permissions
  for select to authenticated using (true);

drop policy if exists "administrators manage role permissions" on public.role_permissions;
create policy "administrators manage role permissions" on public.role_permissions
  for all to authenticated using (public.current_user_has_permission('manage_roles'))
  with check (public.current_user_has_permission('manage_roles'));

drop policy if exists "administrators manage the catalogue" on public.permissions;
create policy "administrators manage the catalogue" on public.permissions
  for all to authenticated using (public.current_user_has_permission('manage_roles'))
  with check (public.current_user_has_permission('manage_roles'));

drop policy if exists "members and admins read teams" on public.teams;
create policy "members and admins read teams" on public.teams
  for select to authenticated using (
    visibility = 'organisation'
    or exists (select 1 from public.team_members tm where tm.team_id = teams.id and tm.user_id = auth.uid())
    or public.current_user_is_admin()
  );

drop policy if exists "team creation" on public.teams;
create policy "team creation" on public.teams
  for insert to authenticated with check (
    public.current_user_has_permission('create_teams') and created_by = auth.uid()
  );

drop policy if exists "team owners and managers update teams" on public.teams;
create policy "team owners and managers update teams" on public.teams
  for update to authenticated using (
    exists (select 1 from public.team_members tm where tm.team_id = teams.id and tm.user_id = auth.uid() and tm.team_role in ('team_owner', 'team_manager'))
    or public.current_user_has_permission('manage_teams')
  );

drop policy if exists "team members read membership" on public.team_members;
create policy "team members read membership" on public.team_members
  for select to authenticated using (
    exists (select 1 from public.team_members tm where tm.team_id = team_members.team_id and tm.user_id = auth.uid())
    or public.current_user_is_admin()
  );

drop policy if exists "team owners manage membership" on public.team_members;
create policy "team owners manage membership" on public.team_members
  for all to authenticated using (
    exists (select 1 from public.team_members tm where tm.team_id = team_members.team_id and tm.user_id = auth.uid() and tm.team_role in ('team_owner', 'team_manager'))
    or public.current_user_has_permission('manage_teams')
  ) with check (
    exists (select 1 from public.team_members tm where tm.team_id = team_members.team_id and tm.user_id = auth.uid() and tm.team_role in ('team_owner', 'team_manager'))
    or public.current_user_has_permission('manage_teams')
  );

drop policy if exists "authorised readers read projects" on public.projects;
create policy "authorised readers read projects" on public.projects
  for select to authenticated using (
    owner_id = auth.uid()
    or exists (select 1 from public.project_members pm where pm.project_id = projects.id and pm.user_id = auth.uid())
    or (visibility = 'organisation' and public.current_user_is_active())
    or (visibility = 'team' and team_id is not null and public.current_user_is_team_member(team_id))
    or public.current_user_is_admin()
  );

drop policy if exists "project creation" on public.projects;
create policy "project creation" on public.projects
  for insert to authenticated with check (
    owner_id = auth.uid()
    and (
      visibility = 'private'
      or (visibility = 'team' and public.current_user_has_permission('create_projects'))
      or (visibility = 'organisation' and public.current_user_has_permission('manage_projects'))
    )
  );

drop policy if exists "project owners update projects" on public.projects;
create policy "project owners update projects" on public.projects
  for update to authenticated using (
    owner_id = auth.uid()
    or exists (select 1 from public.project_members pm where pm.project_id = projects.id and pm.user_id = auth.uid() and pm.project_role in ('owner', 'manager'))
    or public.current_user_has_permission('manage_projects')
  );

drop policy if exists "project readers read members" on public.project_members;
create policy "project readers read members" on public.project_members
  for select to authenticated using (public.current_user_can_access_project(project_id));

drop policy if exists "project owners manage members" on public.project_members;
create policy "project owners manage members" on public.project_members
  for all to authenticated using (
    exists (select 1 from public.projects pr where pr.id = project_members.project_id and pr.owner_id = auth.uid())
    or exists (select 1 from public.project_members pm where pm.project_id = project_members.project_id and pm.user_id = auth.uid() and pm.project_role in ('owner', 'manager'))
    or public.current_user_has_permission('manage_project_members')
  ) with check (
    exists (select 1 from public.projects pr where pr.id = project_members.project_id and pr.owner_id = auth.uid())
    or exists (select 1 from public.project_members pm where pm.project_id = project_members.project_id and pm.user_id = auth.uid() and pm.project_role in ('owner', 'manager'))
    or public.current_user_has_permission('manage_project_members')
  );

drop policy if exists "users read own resource access" on public.resource_access;
create policy "users read own resource access" on public.resource_access
  for select to authenticated using (user_id = auth.uid() or public.current_user_is_admin());

drop policy if exists "authorised staff manage resource access" on public.resource_access;
create policy "authorised staff manage resource access" on public.resource_access
  for all to authenticated using (
    public.current_user_has_permission('manage_document_permissions') or public.current_user_is_admin()
  ) with check (
    public.current_user_has_permission('manage_document_permissions') or public.current_user_is_admin()
  );

drop policy if exists "approval visibility" on public.approval_requests;
create policy "approval visibility" on public.approval_requests
  for select to authenticated using (
    requested_by = auth.uid()
    or assigned_approver = auth.uid()
    or public.current_user_has_permission('assign_permissions')
    or public.current_user_has_permission('approve_reports')
  );

drop policy if exists "approval creation" on public.approval_requests;
create policy "approval creation" on public.approval_requests
  for insert to authenticated with check (requested_by = auth.uid());

drop policy if exists "approver decisions" on public.approval_requests;
create policy "approver decisions" on public.approval_requests
  for update to authenticated using (
    assigned_approver = auth.uid()
    or public.current_user_has_permission('assign_permissions')
    or requested_by = auth.uid()
  );

drop policy if exists "leave visibility" on public.leave_requests;
create policy "leave visibility" on public.leave_requests
  for select to authenticated using (
    user_id = auth.uid()
    or public.current_user_has_permission('approve_leave')
    or public.current_user_has_permission('manage_leave')
    or public.current_user_has_permission('view_team_attendance')
  );

drop policy if exists "leave creation" on public.leave_requests;
create policy "leave creation" on public.leave_requests
  for insert to authenticated with check (user_id = auth.uid() and public.current_user_has_permission('request_leave'));

drop policy if exists "leave decisions" on public.leave_requests;
create policy "leave decisions" on public.leave_requests
  for update to authenticated using (
    public.current_user_has_permission('approve_leave') or public.current_user_has_permission('manage_leave') or user_id = auth.uid()
  );
